// src/application/resolve-chat-header.js
async function resolveChatHeader({ conversation, user, repository: repository2, logger: logger2 }) {
  if (!isDirectConversation(conversation)) {
    return { title: displayConversationTitle(conversation, null), peer: null };
  }
  let peer = conversation.other_profile || conversation.peer_profile || null;
  if (!peer && conversation.other_user) peer = conversation.other_user;
  try {
    if (peer?.id && typeof repository2.getPeerPresence === "function") {
      const presence = await repository2.getPeerPresence(peer.id);
      if (presence.ok && presence.value) peer = { ...peer, ...presence.value };
      else if (!presence.ok) logger2?.warn("chat.peer.presence.failed", { conversationId: conversation.id, message: presence.error?.message });
    } else {
      const result = await repository2.getDirectPeer(conversation.id, user.id);
      if (result.ok && result.value) peer = result.value;
      else if (!result.ok) logger2?.warn("chat.peer.resolve.failed", {
        conversationId: conversation.id,
        message: result.error?.message
      });
    }
  } catch (error) {
    logger2?.warn("chat.peer.resolve.exception", { conversationId: conversation.id, message: error?.message });
  }
  return {
    title: displayConversationTitle(conversation, peer),
    peer
  };
}

