        host.innerHTML = `<div class="token-head"><b>\u041D\u043E\u0432\u044B\u0439 \u0442\u043E\u043A\u0435\u043D \u0441\u043E\u0437\u0434\u0430\u043D</b><span>\u041F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0438\u0439 \u0442\u043E\u043A\u0435\u043D \u043E\u0442\u043E\u0437\u0432\u0430\u043D</span></div><code>${esc(result.token)}</code><button type="button" data-bot-action="copy-token">\u041A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0442\u043E\u043A\u0435\u043D</button><p>\u0421\u043E\u0445\u0440\u0430\u043D\u0438 \u0442\u043E\u043A\u0435\u043D \u0441\u0435\u0439\u0447\u0430\u0441. \u041F\u043E\u0432\u0442\u043E\u0440\u043D\u043E \u043F\u043E\u043A\u0430\u0437\u0430\u0442\u044C \u0435\u0433\u043E \u043D\u0435\u043B\u044C\u0437\u044F.</p>`;
        this.notify("\u0422\u043E\u043A\u0435\u043D \u0431\u043E\u0442\u0430 \u043E\u0431\u043D\u043E\u0432\u043B\u0451\u043D.");
