    const cryptoRef = this.window?.crypto || globalThis.crypto;
    if (!cryptoRef?.subtle || !cryptoRef?.getRandomValues) throw new Error("\u0411\u0440\u0430\u0443\u0437\u0435\u0440 \u043D\u0435 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442 \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u0443\u044E \u043A\u0440\u0438\u043F\u0442\u043E\u0433\u0440\u0430\u0444\u0438\u044E. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 RIM \u043F\u043E HTTPS.");
