      if (!state || state !== pending4.state) throw new Error("\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 state \u043D\u0435 \u043F\u0440\u043E\u0439\u0434\u0435\u043D\u0430. \u0412\u043E\u0437\u043C\u043E\u0436\u043D\u0430 \u043F\u043E\u0434\u043C\u0435\u043D\u0430 \u0437\u0430\u043F\u0440\u043E\u0441\u0430.");
      if (!pending4.createdAt || Date.now() - pending4.createdAt > 10 * 60 * 1e3) throw new Error("\u0417\u0430\u043F\u0440\u043E\u0441 \u0432\u0445\u043E\u0434\u0430 Telegram \u0443\u0441\u0442\u0430\u0440\u0435\u043B. \u041D\u0430\u0447\u043D\u0438\u0442\u0435 \u0437\u0430\u043D\u043E\u0432\u043E.");
      if (pending4.redirectUri !== this.#redirectUri()) throw new Error("\u0410\u0434\u0440\u0435\u0441 \u0432\u043E\u0437\u0432\u0440\u0430\u0442\u0430 \u0438\u0437\u043C\u0435\u043D\u0438\u043B\u0441\u044F. \u041D\u0430\u0447\u043D\u0438\u0442\u0435 \u0432\u0445\u043E\u0434 \u0437\u0430\u043D\u043E\u0432\u043E.");
