// src/application/auth-form-controller.js
var AuthFormController = class {
  constructor({
    client,
    documentRef = globalThis.document,
    windowRef = globalThis.window,
    onSignedIn = async () => {
    },
    logger: logger2 = null
  } = {}) {
    this.client = client;
    this.document = documentRef;
    this.window = windowRef;
    this.onSignedIn = onSignedIn;
    this.logger = logger2;
    this.mode = "login";
    this.busy = false;
    this.telegramAuth = new TelegramAuthService({ client, windowRef });
    this.recoveryCodes = new RecoveryCodesService({ client });
  }
  #el(id2) {
    return this.document.getElementById?.(id2) || null;
  }
  #setStatus(text2) {
    const status = this.#el("authStatus");
    if (status) status.textContent = text2 || "";
  }
  showLoginForm() {
    this.mode = "login";
    const extra = this.#el("signupExtras");
    if (extra) extra.hidden = true;
    const reg = this.#el("registerBtn");
    const login = this.#el("loginBtn");
    const pass = this.#el("authPassword");
    if (reg) {
      reg.textContent = "\u0420\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044F";
      reg.onclick = () => this.startRegistration();
    }
    if (login) {
      login.textContent = "\u0412\u043E\u0439\u0442\u0438";
      login.onclick = () => {
        this.signIn();
      };
    }
    if (pass) {
      pass.autocomplete = "current-password";
      pass.placeholder = "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u043F\u0430\u0440\u043E\u043B\u044C";
    }
    const label = this.#el("passwordLabel");
    if (label) label.textContent = "\u041F\u0430\u0440\u043E\u043B\u044C \u0434\u043B\u044F \u0432\u0445\u043E\u0434\u0430";
    const confirm2 = this.#el("authPasswordConfirm");
    if (confirm2) confirm2.value = "";
    this.#setStatus("");
  }
  startRegistration() {
    this.mode = "signup";
    const extra = this.#el("signupExtras");
    if (extra) extra.hidden = false;
    const reg = this.#el("registerBtn");
    const login = this.#el("loginBtn");
    const pass = this.#el("authPassword");
    if (reg) {
      reg.textContent = "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u0430\u043A\u043A\u0430\u0443\u043D\u0442";
      reg.onclick = () => {
        this.signUp();
      };
    }
    if (login) {
      login.textContent = "\u041D\u0430\u0437\u0430\u0434 \u043A\u043E \u0432\u0445\u043E\u0434\u0443";
      login.onclick = () => this.showLoginForm();
    }
    if (pass) pass.autocomplete = "new-password";
    const label = this.#el("passwordLabel");
    if (label) label.textContent = "\u041F\u0440\u0438\u0434\u0443\u043C\u0430\u0439\u0442\u0435 \u043F\u0430\u0440\u043E\u043B\u044C \u0434\u043B\u044F \u0432\u0445\u043E\u0434\u0430";
    this.#setStatus("\u0423\u043A\u0430\u0436\u0438\u0442\u0435 \u043F\u043E\u0447\u0442\u0443, \u043F\u0440\u0438\u0434\u0443\u043C\u0430\u0439\u0442\u0435 \u043F\u0430\u0440\u043E\u043B\u044C \u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u0435\u0433\u043E.");
    this.#el("authPasswordConfirm")?.focus?.();
  }
  togglePassword(id2, button) {
    const input = this.#el(id2);
    if (!input) return;
    input.type = input.type === "password" ? "text" : "password";
    if (button) button.textContent = input.type === "password" ? "\u041F\u043E\u043A\u0430\u0437\u0430\u0442\u044C" : "\u0421\u043A\u0440\u044B\u0442\u044C";
  }
  async signIn() {
    if (this.busy) return Err(new Error("busy"));
    if (!this.client?.auth) {
      this.#setStatus("\u0421\u0435\u0440\u0432\u0438\u0441 \u0432\u0445\u043E\u0434\u0430 \u043F\u043E\u043A\u0430 \u043D\u0435 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u043B\u0441\u044F. \u041E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443.");
      return Err(new Error("no client"));
    }
    const parsed = validateLoginCredentials(
      this.#el("authEmail")?.value,
      this.#el("authPassword")?.value
    );
    if (!parsed.ok) {
      this.#setStatus(parsed.error);
      return Err(new Error(parsed.error));
    }
    this.busy = true;
    const button = this.#el("loginBtn");
    if (button) button.disabled = true;
    this.#setStatus("\u041F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u043C \u0434\u0430\u043D\u043D\u044B\u0435\u2026");
    try {
      const { data, error } = await this.client.auth.signInWithPassword({
        email: parsed.email,
        password: parsed.password
      });
      if (error) {
        const m = error.message || "";
        if (/invalid login credentials/i.test(m)) {
          this.#setStatus("\u041F\u043E\u0447\u0442\u0430 \u0438\u043B\u0438 \u043F\u0430\u0440\u043E\u043B\u044C \u043D\u0435\u0432\u0435\u0440\u043D\u044B. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u0438 \u043F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0435\u0449\u0451 \u0440\u0430\u0437.");
        } else if (/email not confirmed/i.test(m)) {
          this.#setStatus("\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u0430\u0434\u0440\u0435\u0441 \u044D\u043B\u0435\u043A\u0442\u0440\u043E\u043D\u043D\u043E\u0439 \u043F\u043E\u0447\u0442\u044B \u043F\u043E \u0441\u0441\u044B\u043B\u043A\u0435 \u0438\u0437 \u043F\u0438\u0441\u044C\u043C\u0430.");
        } else {
          this.#setStatus(m);
        }
        return Err(error);
      }
      this.window.currentUser = data.user;
      await this.onSignedIn(data.user);
      return Ok(data.user);
    } finally {
      this.busy = false;
      if (button) button.disabled = false;
    }
  }
  async signUp() {
    if (this.busy) return Err(new Error("busy"));
    if (!this.client?.auth) {
      this.#setStatus("\u0421\u0435\u0440\u0432\u0438\u0441 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438 \u043F\u043E\u043A\u0430 \u043D\u0435 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u043B\u0441\u044F.");
      return Err(new Error("no client"));
    }
    const parsed = validateRegistrationCredentials(
      this.#el("authEmail")?.value,
      this.#el("authPassword")?.value,
      this.#el("authPasswordConfirm")?.value
    );
    if (!parsed.ok) {
      this.#setStatus(parsed.error);
      return Err(new Error(parsed.error));
    }
    this.busy = true;
    const regBtn = this.#el("registerBtn");
    if (regBtn) regBtn.disabled = true;
    this.#setStatus("\u0421\u043E\u0437\u0434\u0430\u0451\u043C \u0430\u043A\u043A\u0430\u0443\u043D\u0442...");
    try {
      const { data, error } = await this.client.auth.signUp({
        email: parsed.email,
        password: parsed.password
      });
      if (error) {
        this.#setStatus(error.message || String(error));
        return Err(error);
      }
      if (data.session) {
        this.window.currentUser = data.user;
        await this.onSignedIn(data.user);
      } else {
        this.#setStatus("\u0420\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044F \u0441\u043E\u0437\u0434\u0430\u043D\u0430. \u041F\u0440\u043E\u0432\u0435\u0440\u044C \u043F\u043E\u0447\u0442\u0443 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438 \u0430\u0434\u0440\u0435\u0441.");
        this.showLoginForm();
      }
      return Ok(data.user || null);
    } finally {
      this.busy = false;
      if (regBtn) regBtn.disabled = false;
    }
  }
  async resetPassword() {
    const parsed = validateEmail(this.#el("authEmail")?.value);
    if (!parsed.ok) {
      this.#setStatus(parsed.error.includes("\u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0439") ? "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0443\u043A\u0430\u0436\u0438\u0442\u0435 \u044D\u043B\u0435\u043A\u0442\u0440\u043E\u043D\u043D\u0443\u044E \u043F\u043E\u0447\u0442\u0443, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043E\u0432\u0430\u043D \u0430\u043A\u043A\u0430\u0443\u043D\u0442." : parsed.error);
      return Err(new Error(parsed.error));
    }
    try {
      const { error } = await this.client.auth.resetPasswordForEmail(parsed.email);
      if (error) throw error;
      this.#setStatus("\u0415\u0441\u043B\u0438 \u0430\u043A\u043A\u0430\u0443\u043D\u0442 \u0441 \u0442\u0430\u043A\u0438\u043C \u0430\u0434\u0440\u0435\u0441\u043E\u043C \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442, \u043F\u0438\u0441\u044C\u043C\u043E \u0434\u043B\u044F \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u043E.");
      return Ok(true);
    } catch (error) {
      this.#setStatus(error?.message || String(error));
      return Err(error);
    }
  }
  async signInWithSeedPhrase() {
    if (this.busy) return Err(new Error("busy"));
    const phrase = this.#el("rimSeedLoginPhrase")?.value || "";
    this.busy = true;
    const button = this.#el("rimSeedLoginSubmit");
    if (button) button.disabled = true;
    this.#setStatus("\u041F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u043C \u0441\u0435\u043A\u0440\u0435\u0442\u043D\u0443\u044E \u0444\u0440\u0430\u0437\u0443 \u0438 \u043F\u043E\u0434\u0433\u043E\u0442\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u043C \u0437\u0430\u0449\u0438\u0449\u0451\u043D\u043D\u0443\u044E \u0441\u0435\u0441\u0441\u0438\u044E\u2026");
    try {
      const user = await this.recoveryCodes.seedLogin(phrase);
      this.window.currentUser = user;
      const input = this.#el("rimSeedLoginPhrase");
      if (input) input.value = "";
      this.#setStatus("\u0412\u0445\u043E\u0434 \u043F\u043E \u0441\u0435\u043A\u0440\u0435\u0442\u043D\u043E\u0439 \u0444\u0440\u0430\u0437\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D. \u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u043C RIM\u2026");
      await this.onSignedIn(user);
      return Ok(user);
    } catch (error) {
      this.#setStatus(error?.message || "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0432\u043E\u0439\u0442\u0438 \u043F\u043E \u0441\u0435\u043A\u0440\u0435\u0442\u043D\u043E\u0439 \u0444\u0440\u0430\u0437\u0435.");
      return Err(error);
    } finally {
      this.busy = false;
      if (button) button.disabled = false;
    }
  }
  async recoverWithPhrase() {
    if (this.busy) return Err(new Error("busy"));
    const phrase = this.#el("rimRecoveryPhrase")?.value || "";
    this.busy = true;
    const button = this.#el("rimRecoveryPhraseSubmit");
    if (button) button.disabled = true;
    this.#setStatus("\u041F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u043C \u0441\u0435\u043A\u0440\u0435\u0442\u043D\u0443\u044E \u0444\u0440\u0430\u0437\u0443 RIM\u2026");
    try {
      const user = await this.recoveryCodes.redeemPhrase(phrase);
      this.window.currentUser = user;
      this.#setStatus("\u0414\u043E\u0441\u0442\u0443\u043F \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D. \u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u043C RIM\u2026");
      await this.onSignedIn(user);
      return Ok(user);
    } catch (error) {
      this.#setStatus(error?.message || "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0434\u043E\u0441\u0442\u0443\u043F. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0444\u0440\u0430\u0437\u0443.");
      return Err(error);
    } finally {
      this.busy = false;
      if (button) button.disabled = false;
    }
  }
  async recoverWithCode() {
    if (this.busy) return Err(new Error("busy"));
    const code = this.#el("rimRecoveryCode")?.value || "";
    this.busy = true;
    const button = this.#el("rimRecoverySubmit");
    if (button) button.disabled = true;
    this.#setStatus("\u041F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u043C \u043E\u0434\u043D\u043E\u0440\u0430\u0437\u043E\u0432\u044B\u0439 \u043A\u043E\u0434 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F\u2026");
    try {
      const user = await this.recoveryCodes.redeem(code);
      this.window.currentUser = user;
      this.#setStatus("\u0414\u043E\u0441\u0442\u0443\u043F \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D. \u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u043C RIM\u2026");
      await this.onSignedIn(user);
      return Ok(user);
    } catch (error) {
      this.#setStatus(error?.message || "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0434\u043E\u0441\u0442\u0443\u043F. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u043A\u043E\u0434.");
      return Err(error);
    } finally {
      this.busy = false;
      if (button) button.disabled = false;
    }
  }
  async signInWithTelegram() {
    if (this.busy) return Err(new Error("busy"));
    this.busy = true;
    const button = this.#el("telegramAuthBtn");
    if (button) button.disabled = true;
    this.#setStatus("\u041F\u043E\u0434\u0433\u043E\u0442\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u043C \u0437\u0430\u0449\u0438\u0449\u0451\u043D\u043D\u044B\u0439 \u0432\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 Telegram\u2026");
    try {
      await this.telegramAuth.start();
      return Ok(true);
    } catch (error) {
      this.#setStatus(error?.message || "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043D\u0430\u0447\u0430\u0442\u044C \u0432\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 Telegram.");
      return Err(error);
    } finally {
      this.busy = false;
      if (button) button.disabled = false;
    }
  }
  async handleTelegramCallback() {
    const result = await this.telegramAuth.handleCallback();
    if (!result.handled) return result;
    if (!result.ok) {
      this.#setStatus(result.error?.message || "\u0412\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 Telegram \u043D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D.");
      return Err(result.error || new Error("Telegram sign-in failed"));
    }
    this.window.currentUser = result.user;
    this.#setStatus("\u0412\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 Telegram \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D. \u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u043C RIM\u2026");
    try {
      await this.onSignedIn(result.user);
      this.#setStatus("\u0412\u044B \u0432\u043E\u0448\u043B\u0438 \u0447\u0435\u0440\u0435\u0437 Telegram. \u0420\u0418\u041C \u0433\u043E\u0442\u043E\u0432 \u043A \u0440\u0430\u0431\u043E\u0442\u0435.");
      return Ok(result.user);
    } catch (error) {
      this.#setStatus(`Telegram \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043B \u0432\u0445\u043E\u0434, \u043D\u043E \u0420\u0418\u041C \u043D\u0435 \u0441\u043C\u043E\u0433 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044C \u0434\u0430\u043D\u043D\u044B\u0435: ${error?.message || error}`);
      return Err(error);
    }
  }
  signInWithGithub() {
    this.#setStatus("\u0412\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 GitHub \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0432 \u0440\u0430\u0437\u0440\u0430\u0431\u043E\u0442\u043A\u0435.");
    return Err(new Error("GitHub sign-in is not configured"));
  }
  signInWithVk() {
    this.#setStatus("\u0412\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 VK \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0432 \u0440\u0430\u0437\u0440\u0430\u0431\u043E\u0442\u043A\u0435.");
    return Err(new Error("VK sign-in is not configured"));
  }
  /**
   * OAuth Google via Supabase. Requires provider enabled in Supabase + Google Cloud client.
   * Same flow covers first-time registration and returning sign-in.
   */
  async signInWithGoogle() {
    if (this.busy) return Err(new Error("busy"));
    if (!this.client?.auth?.signInWithOAuth) {
      this.#setStatus("\u0421\u0435\u0440\u0432\u0438\u0441 \u0432\u0445\u043E\u0434\u0430 \u0447\u0435\u0440\u0435\u0437 Google \u043F\u043E\u043A\u0430 \u043D\u0435 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u043B\u0441\u044F. \u041E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443.");
      return Err(new Error("no client"));
    }
    this.busy = true;
    const btn = this.#el("googleAuthBtn");
    if (btn) btn.disabled = true;
    this.#setStatus("\u041F\u0435\u0440\u0435\u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0432 Google\u2026");
    try {
      const redirectTo = `${this.window.location.origin}${this.window.location.pathname || "/"}`;
      const { data, error } = await this.client.auth.signInWithOAuth({
        provider: "google",
        options: {
          redirectTo,
          queryParams: { access_type: "offline", prompt: "consent" }
        }
      });
      if (error) {
        this.#setStatus(error.message || "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043D\u0430\u0447\u0430\u0442\u044C \u0432\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 Google.");
        return Err(error);
      }
      if (data?.url) {
        this.window.location.href = data.url;
      }
      return Ok(data || true);
    } catch (error) {
      this.#setStatus(error?.message || String(error));
      return Err(error);
    } finally {
      this.busy = false;
      if (btn) btn.disabled = false;
    }
  }
  bindGlobals() {
    const win = this.window;
    win.__RIM_AUTH_FORM_OWNED = true;
    win.showLoginForm = () => this.showLoginForm();
    win.startRegistration = () => this.startRegistration();
    win.rimTogglePassword = (id2, button) => this.togglePassword(id2, button);
    win.rimResetPassword = () => this.resetPassword();
    win.rimRecoverWithCode = () => this.recoverWithCode();
    win.rimRecoverWithPhrase = () => this.recoverWithPhrase();
    win.rimSignInWithSeedPhrase = () => this.signInWithSeedPhrase();
    win.signIn = () => this.signIn();
    win.signUp = () => this.signUp();
    win.signInWithGoogle = () => this.signInWithGoogle();
    win.signInWithTelegram = () => this.signInWithTelegram();
    win.signInWithGithub = () => this.signInWithGithub();
    win.signInWithVk = () => this.signInWithVk();
    void this.handleTelegramCallback();
  }
};

// src/application/search-controller.js
var SearchController = class {
  constructor({
    client,
    documentRef = globalThis.document,
    windowRef = globalThis.window,
    openPage = null,
    logger: logger2 = null
  } = {}) {
    this.client = client;
    this.document = documentRef;
    this.window = windowRef;
    this.openPage = openPage || ((title, html) => this.window?.fullPage?.(title, html));
    this.logger = logger2;
    this.kind = "all";
    this.timer = null;
    this.sequence = 0;
    this.disposed = false;
  }
  open() {
    if (this.disposed) return;
    this.kind = "all";
    this.openPage(
      "\u041F\u043E\u0438\u0441\u043A \u0432 \u0420\u0418\u041C\u0435",
      `<input id="rimSearchInput" class="field" placeholder="\u0418\u043C\u044F, @username, \u043A\u0430\u043D\u0430\u043B \u0438\u043B\u0438 \u0441\u043E\u043E\u0431\u0449\u0435\u0441\u0442\u0432\u043E">
       <div class="rim-search-tabs">
         <button type="button" class="action-btn active" data-rim-search-kind="all">\u0412\u0441\u0451</button>
         <button type="button" class="action-btn" data-rim-search-kind="users">\u041B\u044E\u0434\u0438</button>
         <button type="button" class="action-btn" data-rim-search-kind="channels">\u041A\u0430\u043D\u0430\u043B\u044B</button>
         <button type="button" class="action-btn" data-rim-search-kind="groups">\u0413\u0440\u0443\u043F\u043F\u044B</button>
       </div>
       <div id="rimSearchResults"><div class="empty-state">\u041D\u0430\u0447\u043D\u0438\u0442\u0435 \u0432\u0432\u043E\u0434\u0438\u0442\u044C \u0437\u0430\u043F\u0440\u043E\u0441.</div></div>`
    );
    const input = this.document.getElementById("rimSearchInput");
    input?.addEventListener("input", () => this.schedule());
    this.document.querySelectorAll?.("[data-rim-search-kind]")?.forEach?.((button) => {
      button.addEventListener("click", () => this.setKind(button.dataset.rimSearchKind, button));
    });
  }
  setKind(kind, button = null) {
    this.kind = kind || "all";
    this.window.__rimSearchKind = this.kind;
    this.document.querySelectorAll?.(".rim-search-tabs button")?.forEach?.((node) => {
      node.classList.toggle("active", node === button || node.dataset?.rimSearchKind === this.kind);
    });
    this.schedule(0);
  }
  schedule(delay = 350) {
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      void this.run();
    }, delay);
  }
  async run() {
    if (this.disposed) return;
    const sequence = ++this.sequence;
    const out = this.document.getElementById("rimSearchResults");
    if (!out) return;
    const q = String(this.document.getElementById("rimSearchInput")?.value || "").trim().replace(/^@/, "");
    if (q.length < 2) {
      out.innerHTML = '<div class="empty-state">\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u043D\u0435 \u043C\u0435\u043D\u0435\u0435 \u0434\u0432\u0443\u0445 \u0441\u0438\u043C\u0432\u043E\u043B\u043E\u0432.</div>';
      return;
    }
    out.innerHTML = '<div class="notice">\u041F\u043E\u0438\u0441\u043A...</div>';
    try {
      const parts = [];
      if (this.kind === "all" || this.kind === "users") {
        parts.push(this.#searchUsers(q));
      } else {
        parts.push(Promise.resolve(""));
      }
      if (this.kind === "all" || this.kind === "channels") {
        parts.push(this.#searchChannels(q));
      } else {
        parts.push(Promise.resolve(""));
      }
      if (this.kind === "all" || this.kind === "groups") {
        parts.push(this.#searchGroups(q));
      } else {
        parts.push(Promise.resolve(""));
      }
      const chunks2 = await Promise.all(parts);
      if (sequence !== this.sequence) return;
      const html = chunks2.join("");
      out.innerHTML = html || '<div class="empty-state">\u041D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u043E.</div>';
    } catch (error) {
      if (sequence !== this.sequence) return;
      this.logger?.warn?.("search.failed", { message: error?.message });
      out.innerHTML = `<div class="notice">\u041F\u043E\u0438\u0441\u043A \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D: ${escapeHtml8(error?.message || error)}</div>`;
    }
  }
  async #searchUsers(q) {
    const { data, error } = await this.client.from("profiles").select("id,username,display_name,avatar_path,avatar_url").or(`username.ilike.%${q}%,display_name.ilike.%${q}%`).limit(15);
    if (error) throw error;
    const rows = [];
    for (const profile of data || []) {
      let url = profile.avatar_url || "";
      if (profile.avatar_path) {
        try {
          const { data: signed } = await this.client.storage.from("avatars").createSignedUrl(profile.avatar_path, 3600);
          url = signed?.signedUrl || url;
        } catch {
        }
      }
      const username = escapeHtml8(profile.username || "");
      rows.push(`<div class="rim-search-result" data-rim-search-user="${username}">
        ${avatarMarkup(url, profile.display_name || profile.username)}
        <div><b>${escapeHtml8(profile.display_name || profile.username)}</b>
        <div class="feature-small">@${username}</div></div></div>`);
    }
    const html = rows.join("");
    queueMicrotask(() => {
      this.document.querySelectorAll?.("[data-rim-search-user]")?.forEach?.((node) => {
        node.addEventListener("click", () => {
          this.window?.closePage?.();
          this.window?.findUserByName?.(node.getAttribute("data-rim-search-user"));
        });
      });
    });
    return html;
  }
  async #searchChannels(q) {
    const { data, error } = await this.client.from("channels").select("id,title,username,description,avatar_path").or(`title.ilike.%${q}%,username.ilike.%${q}%`).eq("is_public", true).limit(15);
    if (error) throw error;
    return (data || []).map((channel) => {
      const id2 = escapeHtml8(channel.id);
      return `<div class="rim-search-result" data-rim-search-channel="${id2}">
        ${avatarMarkup("", channel.title)}
        <div><b>${escapeHtml8(channel.title)}</b>
        <div class="feature-small">${channel.username ? "@" + escapeHtml8(channel.username) : "\u041A\u0430\u043D\u0430\u043B"} \xB7 ${escapeHtml8(channel.description || "")}</div></div></div>`;
    }).join("") + this.#bindChannelClicks();
  }
  #bindChannelClicks() {
    queueMicrotask(() => {
      this.document.querySelectorAll?.("[data-rim-search-channel]")?.forEach?.((node) => {
        if (node.dataset.bound) return;
        node.dataset.bound = "1";
        node.addEventListener("click", () => {
          this.window?.closePage?.();
          this.window?.openChannel?.(node.getAttribute("data-rim-search-channel"));
        });
      });
    });
    return "";
  }
  async #searchGroups(q) {
    const { data: groups, error } = await this.client.from("conversations").select("id,title,username,avatar_path").eq("type", "group").eq("is_public", true).or(`title.ilike.%${q}%,username.ilike.%${q}%`).limit(15);
    if (error) throw error;
    return (groups || []).map((group) => {
      const id2 = escapeHtml8(group.id);
      const letter = escapeHtml8(String(group.title || "\u0413").slice(0, 1));
      return `<div class="rim-search-result">
        <div class="avatar">${letter}</div>
        <div class="grow"><b>${escapeHtml8(group.title || "\u0413\u0440\u0443\u043F\u043F\u0430")}</b>
        <div class="feature-small">${group.username ? "@" + escapeHtml8(group.username) : "\u041F\u0443\u0431\u043B\u0438\u0447\u043D\u0430\u044F \u0433\u0440\u0443\u043F\u043F\u0430"}</div></div>
        <button type="button" class="action-btn" data-rim-join-group="${id2}">\u0412\u0441\u0442\u0443\u043F\u0438\u0442\u044C</button></div>`;
    }).join("") + this.#bindGroupJoins();
  }
  #bindGroupJoins() {
    queueMicrotask(() => {
      this.document.querySelectorAll?.("[data-rim-join-group]")?.forEach?.((node) => {
        if (node.dataset.bound) return;
        node.dataset.bound = "1";
        node.addEventListener("click", (event) => {
          event.preventDefault();
          this.window?.rimJoinPublicGroup?.(node.getAttribute("data-rim-join-group"));
        });
      });
    });
    return "";
  }
  dispose() {
    this.disposed = true;
    if (this.timer) clearTimeout(this.timer);
    this.sequence += 1;
  }
};
function escapeHtml8(value) {
  return String(value ?? "").replace(/[&<>"']/g, (ch) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  })[ch]);
}
function avatarMarkup(url, title) {
  if (url) {
    return `<div class="avatar"><img src="${escapeHtml8(url)}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:inherit"></div>`;
  }
  const letter = escapeHtml8(String(title || "?").trim().slice(0, 1).toUpperCase() || "?");
  return `<div class="avatar">${letter}</div>`;
}

// src/application/tabbar-controller.js
var TabbarController = class {
  constructor({ documentRef = globalThis.document, windowRef = globalThis.window } = {}) {
    this.document = documentRef;
    this.window = windowRef;
    this.observer = null;
    this.timers = [];
    this.styleEl = null;
  }
  makeButton(id2, label, handler) {
    const doc = this.document;
    let el = doc.getElementById(id2);
    if (!el) {
      el = doc.createElement("button");
      el.type = "button";
      el.id = id2;
      el.className = "action-btn";
      el.textContent = label;
    }
    el.onclick = handler;
    return el;
  }
  install() {
    const doc = this.document;
    const win = this.window;
    const bar = doc.querySelector(".tabbar");
    if (!bar) return false;
    doc.getElementById("tabMore")?.remove();
    doc.getElementById("tabLocalSuite")?.remove();
    const more = this.makeButton("tabMoreFull", "\u0415\u0449\u0451", () => {
      if (typeof win.openMorePage === "function") win.openMorePage();
      else if (typeof win.openMore === "function") win.openMore();
      else console.warn("[RIM] openMore missing");
    });
    const tools = this.makeButton("tabToolsFull", "\u0418\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B", () => {
      if (typeof win.openToolsPage === "function") win.openToolsPage();
      else if (typeof win.openTools === "function") win.openTools();
      else console.warn("[RIM] openTools missing");
    });
    if (more.parentNode !== bar) bar.appendChild(more);
    if (tools.parentNode !== bar) bar.appendChild(tools);
    if (more.nextElementSibling !== tools) bar.insertBefore(more, tools);
    return true;
  }
  ensureStyle() {
    const doc = this.document;
    if (doc.getElementById("rim-final-navigation-repair")) return;
    const style = doc.createElement("style");
    style.id = "rim-final-navigation-repair";
    style.textContent = `
  .tabbar #tabToolsFull,.tabbar #tabMoreFull{display:flex!important;visibility:visible!important;opacity:1!important;position:relative!important;flex:1 1 0!important;min-width:0!important;white-space:nowrap!important;order:initial!important;}
  .tabbar #tabMoreFull{order:4!important}
  .tabbar #tabToolsFull{order:5!important}
  #rimFullPage .rim-banner img,.rim-fullpage .rim-banner img{max-height:125px!important;height:auto!important;object-fit:contain!important}
  #rimFullPage .rim-banner,.rim-fullpage .rim-banner{max-height:165px!important;overflow:hidden!important}
 `;
    (doc.head || doc.documentElement).appendChild(style);
    this.styleEl = style;
  }
  start() {
    this.ensureStyle();
    this.install();
    const doc = this.document;
    if (!this.observer && doc.documentElement) {
      this.observer = new MutationObserver(() => this.install());
      this.observer.observe(doc.documentElement, { childList: true, subtree: true });
    }
    for (const ms of [0, 100, 400, 1e3, 2e3, 4e3]) {
      this.timers.push(setTimeout(() => this.install(), ms));
    }
    this.window.addEventListener?.("load", this._onLoad);
  }
  _onLoad = () => {
    this.install();
  };
  dispose() {
    this.observer?.disconnect?.();
    this.observer = null;
    for (const t of this.timers) clearTimeout(t);
    this.timers = [];
    try {
      this.window.removeEventListener?.("load", this._onLoad);
    } catch {
    }
  }
};

