    if (name === "channels") {
      try {
        void this.loadChannels?.();
      } catch (e) {
        this.logger?.warn?.("section.channels.load", e);
      }
    }
    if (name === "music") {
      try {
        void this.loadMusic?.();
      } catch (e) {
        this.logger?.warn?.("section.music.load", e);
      }
    }
