var ComposerChromeController = class {
  constructor({
    documentRef = globalThis.document,
    windowRef = globalThis.window,
    sendMessage = null,
    notify: notify2 = () => {
    },
    logger: logger2 = null
  } = {}) {
    this.document = documentRef;
    this.window = windowRef;
    this.sendMessage = sendMessage;
    this.notify = notify2;
    this.logger = logger2;
    this._bound = false;
  }
  messageKeydown(event) {
    if (!event) return;
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      const send2 = this.sendMessage || this.window?.sendMessage;
      try {
        void send2?.();
      } catch (e) {
        this.logger?.warn?.("composer.send.keydown", e);
      }
    }
  }
  resizeComposer(el) {
    const node = el || this.document?.getElementById?.("messageInput");
    if (!node) return;
    try {
      node.style.height = "auto";
      const next = Math.min(Math.max(node.scrollHeight, 40), 160);
      node.style.height = `${next}px`;
    } catch {
    }
  }
  toggleStickers() {
    const panel = this.document?.getElementById?.("stickerPanel");
    if (!panel) return;
    panel.classList.toggle("hidden");
  }
  openAttachSheet() {
    const doc = this.document;
    doc.getElementById?.("rimAttachSheet")?.remove?.();
    const sheet = doc.createElement("div");
    sheet.id = "rimAttachSheet";
    sheet.className = "rim-attach-sheet";
    sheet.innerHTML = `<div class="rim-msg-sheet-backdrop" onclick="document.getElementById('rimAttachSheet')?.remove()"></div>
    <div class="rim-attach-panel">
      <button type="button" class="rim-attach-item" data-rim-attach="photo">\u{1F4F7} \u041A\u0430\u043C\u0435\u0440\u0430 / \u0424\u043E\u0442\u043E</button>
      <button type="button" class="rim-attach-item" data-rim-attach="gallery">\u{1F5BC} \u0413\u0430\u043B\u0435\u0440\u0435\u044F</button>
      <button type="button" class="rim-attach-item" data-rim-attach="file">\u{1F4C4} \u0424\u0430\u0439\u043B\u044B</button>
      <button type="button" class="rim-attach-item" data-rim-attach="stickers">\u{1F600} \u0421\u0442\u0438\u043A\u0435\u0440\u044B</button>
      <button type="button" class="rim-attach-item" data-rim-attach="connectors">\u{1F50C} \u041A\u043E\u043D\u043D\u0435\u043A\u0442\u043E\u0440\u044B</button>
      <button type="button" class="rim-attach-item" data-rim-attach="close">\u0417\u0430\u043A\u0440\u044B\u0442\u044C</button>
    </div>`;
    sheet.addEventListener("click", (event) => {
      const btn = event.target?.closest?.("[data-rim-attach]");
      if (!btn) return;
      const action = btn.getAttribute("data-rim-attach");
      sheet.remove();
      if (action === "photo" || action === "gallery") {
        doc.getElementById?.("imageInput")?.click?.();
      } else if (action === "file") {
        doc.getElementById?.("fileInput")?.click?.();
      } else if (action === "stickers") {
        this.toggleStickers();
      } else if (action === "connectors") {
        this.notify?.("\u041A\u043E\u043D\u043D\u0435\u043A\u0442\u043E\u0440\u044B \u2014 \u0441\u043A\u043E\u0440\u043E \u0431\u0443\u0434\u0435\u0442 \u0440\u0435\u0430\u043B\u0438\u0437\u043E\u0432\u0430\u043D\u043E.");
      }
    });
    doc.body.appendChild(sheet);
  }
  bindGlobals() {
    const win = this.window;
    win.__RIM_COMPOSER_CHROME_OWNED = true;
    win.messageKeydown = (event) => this.messageKeydown(event);
    win.resizeComposer = (el) => this.resizeComposer(el);
    win.toggleStickers = () => this.toggleStickers();
    win.rimOpenAttachSheet = () => this.openAttachSheet();
  }
  installDomHooks() {
    if (this._bound) return;
    this._bound = true;
    const doc = this.document;
    doc.getElementById?.("rimAttachBtn")?.addEventListener?.("click", () => this.openAttachSheet());
    doc.getElementById?.("rimVoiceBtn")?.addEventListener?.("click", () => {
      if (typeof this.window.rimStartVoiceMessage === "function") this.window.rimStartVoiceMessage();
      else this.notify?.("\u0417\u0430\u043F\u0438\u0441\u044C \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u044B\u0445 \u0441\u043A\u043E\u0440\u043E \u0431\u0443\u0434\u0435\u0442 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430.");
    });
    const input = doc.getElementById?.("messageInput");
    if (input && !input.dataset.rimComposerBound) {
      input.dataset.rimComposerBound = "1";
      input.addEventListener("input", () => this.resizeComposer(input));
    }
  }
  dispose() {
    try {
      this.window.__RIM_COMPOSER_CHROME_OWNED = false;
    } catch {
    }
  }
};

// src/application/viewport-controller.js
var ViewportController = class {
  constructor({
    documentRef = globalThis.document,
    windowRef = globalThis.window,
    logger: logger2 = null
  } = {}) {
    this.document = documentRef;
    this.window = windowRef;
    this.logger = logger2;
    this._onUpdate = () => this.update();
    this._installed = false;
  }
  update() {
    const win = this.window;
    const doc = this.document;
    try {
      const vv = win.visualViewport;
      const h = vv ? vv.height : win.innerHeight;
      doc.documentElement.style.setProperty("--app-height", `${h}px`);
    } catch {
    }
    try {
      const input = doc.getElementById?.("messageInput");
      if (doc.activeElement !== input) return;
      win.requestAnimationFrame?.(() => {
        const messages = doc.getElementById?.("messages");
        if (!messages) return;
        const nearBottom = messages.scrollHeight - messages.scrollTop - messages.clientHeight < 120;
        if (nearBottom) messages.scrollTop = messages.scrollHeight;
      });
    } catch {
    }
  }
  install() {
    if (this._installed) return;
    this._installed = true;
    const win = this.window;
    const doc = this.document;
    if (win.visualViewport) {
      win.visualViewport.addEventListener("resize", this._onUpdate);
      win.visualViewport.addEventListener("scroll", this._onUpdate);
    }
    win.addEventListener("resize", this._onUpdate);
    win.addEventListener("orientationchange", () => {
      win.setTimeout?.(this._onUpdate, 200);
    });
    const input = doc.getElementById?.("messageInput");
    input?.addEventListener?.("focus", () => win.setTimeout?.(this._onUpdate, 100));
    input?.addEventListener?.("blur", () => win.setTimeout?.(this._onUpdate, 100));
    this.update();
  }
  bindGlobals() {
    const win = this.window;
    win.__RIM_VIEWPORT_OWNED = true;
    win.updateViewport = () => this.update();
  }
  dispose() {
    try {
      this.window.__RIM_VIEWPORT_OWNED = false;
    } catch {
    }
  }
};

