// src/application/paint-direct-peer-header.js
async function paintDirectPeerHeader({
  conversation,
  user,
  repository: repository2,
  resolveChatHeader: resolveChatHeader2,
  applyPeerAvatar: applyPeerAvatar2,
  documentRef = globalThis.document,
  isCurrent = () => true,
  sequence = 0,
  logger: logger2 = null
} = {}) {
  if (!conversation || conversation.type !== "direct") return null;
  if (!isCurrent()) return null;
  const cachedPeer = conversation.other_profile || conversation.peer_profile || null;
  const cachedTitle = cachedPeer?.display_name?.trim() || cachedPeer?.username?.trim() || conversation.title || "\u041B\u0438\u0447\u043D\u044B\u0435 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F";
  const titleNode = documentRef.getElementById?.("chatHeadName");
  if (titleNode) titleNode.textContent = cachedTitle;
  const avatarNode = documentRef.getElementById?.("chatHeadAvatar");
  const cachedAvatarTask = applyPeerAvatar2 ? applyPeerAvatar2(avatarNode, cachedPeer, cachedTitle, sequence) : Promise.resolve(null);
  const resolved = await resolveChatHeader2({
    conversation,
    user,
    repository: repository2,
    logger: logger2
  });
  if (!isCurrent()) return null;
  if (titleNode) titleNode.textContent = resolved.title;
  const status = documentRef.getElementById?.("chatHeadStatus");
  const seenAt = resolved.peer?.last_seen_at ? new Date(resolved.peer.last_seen_at) : null;
  const visible = resolved.peer?.showOnline === true || resolved.peer?.show_online === true;
  const validSeen = seenAt && Number.isFinite(seenAt.getTime()) && seenAt.getTime() <= Date.now();
  const online = visible && validSeen && Date.now() - seenAt.getTime() < 12e4;
  if (status) {
    status.textContent = !visible ? "\u0421\u0442\u0430\u0442\u0443\u0441 \u0441\u043A\u0440\u044B\u0442" : online ? "\u0412 \u0441\u0435\u0442\u0438" : validSeen ? `\u0411\u044B\u043B(\u0430) \u0432 \u0441\u0435\u0442\u0438 ${seenAt.toLocaleString("ru-RU")}` : "\u0412\u0440\u0435\u043C\u044F \u043F\u043E\u0441\u0435\u0449\u0435\u043D\u0438\u044F \u043D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043D\u043E";
  }
  if (applyPeerAvatar2) {
    await Promise.all([
      cachedAvatarTask,
      applyPeerAvatar2(avatarNode, resolved.peer, resolved.title, sequence)
    ]);
  }
  return resolved;
}

