          user_id: user.id,
          title: record7.title,
          artist: record7.artist,
          file_path: path,
          visibility: "private",
          file_size: record7.size,
          play_count: record7.plays,
          completed_plays: record7.completedPlays,
          listened_seconds: record7.listenedSeconds,
          daily_plays: record7.dailyPlays,
          is_favorite: record7.favorite,
          last_played_at: record7.lastPlayedAt
