var rimDeepLink = new URLSearchParams(window.location.search || "");
var rimDeepChannel = rimDeepLink.get("channel");
var rimDeepPost = rimDeepLink.get("post");
var rimDeepLinkHandled = false;
var openRimDeepLink = async () => {
  if (rimDeepLinkHandled || !rimDeepChannel || !legacy.getUser?.()?.id) return;
  rimDeepLinkHandled = true;
  try {
    await window.openChannel?.(rimDeepChannel);
    if (rimDeepPost) {
      const target = [...document.querySelectorAll("[data-rim-post-id]")].find((node) => String(node.dataset.rimPostId) === String(rimDeepPost));
      target?.scrollIntoView?.({ behavior: "smooth", block: "center" });
    }
  } catch (error) {
    logger.warn("channel.deep_link.open.failed", { message: error?.message });
  }
};
void openRimDeepLink();
legacy.db.auth?.onAuthStateChange?.((event) => {
  if (event === "SIGNED_IN") void openRimDeepLink();
});
